    t.expect(input.value).toBe("Groceries!");
    t.expect(NotesSupport$WeftNotes.Doc.activeElement() === input).toBe(true);
    t.expect([
      input.selectionStart,
      input.selectionEnd
    ]).toEqual([
      2,
      5
    ]);
    t.expect(WeftTesting.removedSince(page, before)).toEqual([]);
    t.expect(WeftTesting.renderCount(page, likeButton)).toBe(likeRenders);
